# "בטעם קפה", "בניחוח וניל" describe a flavour, not what the product is
_FLAVOR = re.compile(r"\s(?:ב?טעם|בניחוח|ניחוח|בציפוי|ציפוי|במילוי|מילוי|עם)\s+\S+(?:\s+\S+)?")


def normalize(name: str) -> str:
    t = (name or "").replace("׳", "'").replace("״", '"')
    t = re.sub(r"\s+", " ", t).strip()
    t = _FLAVOR.sub(" ", " " + t)
    return " " + re.sub(r"\s+", " ", t).strip() + " "


def _norm_phrase(p: str) -> str:
    return p.replace("׳", "'").replace("״", '"')


def _pattern(p: str):
    """Match at a word start (allowing ה/ו and a glued number), so "קפה" doesn't match "לקפה".
    Short single words must also end at a word end, so "שוקו" doesn't match "שוקולד"."""
    ph = _norm_phrase(p).strip()
    core = re.escape(ph)
    end = r"(?![\u0590-\u05FF])" if (" " not in ph and len(ph) <= 4) or p.endswith(" ") else ""
    return re.compile(r"(?:^|[\s\d\"'(+.-])[הו]?" + core + end)


def _compile(rule):
    cid, label, inc, exc = rule[:4]
    req = rule[4] if len(rule) > 4 else []
    return (cid, label, [_pattern(p) for p in inc], [_norm_phrase(p) for p in exc], [_norm_phrase(p) for p in req])


_COMPILED = [_compile(r) for r in RULES]

LABELS = {r[0]: r[1] for r in RULES}


def categorize(name: str) -> str:
    n = normalize(name)
    raw = " " + (name or "") + " "
    for cid, _label, inc, exc, req in _COMPILED:
        if any(p.search(n) for p in inc) and not any(p in raw for p in exc) and (not req or any(p in raw for p in req)):
            return cid
    return ""
